arguments.file_text:
namespace sv_b3b639e3aa074f7e82b5a699feff4e87.Services;

public record UserProfile(string DisplayName, string Email, string AvatarUrl, string Bio);
public record NotificationPrefs(bool EmailNotifications, bool PushNotifications, bool WeeklyDigest, List<string> MutedChannels);
public record SecuritySettings(bool TwoFactorEnabled, DateTime? LastPasswordChange, List<ActiveSession> Sessions);
public record ActiveSession(string Id, string Device, string Location, DateTime LastActive);
public record AppearanceSettings(string Theme, string FontSize, string Language, bool CompactMode);

public interface ISettingsService
{
    Task<UserProfile> GetProfileAsync();
    Task SaveProfileAsync(UserProfile profile);
    Task<NotificationPrefs> GetNotificationPrefsAsync();
    Task SaveNotificationPrefsAsync(NotificationPrefs prefs);
    Task<SecuritySettings> GetSecuritySettingsAsync();
    Task ChangePasswordAsync(string currentPassword, string newPassword);
    Task RevokeSessionAsync(string sessionId);
    Task<AppearanceSettings> GetAppearanceAsync();
    Task SaveAppearanceAsync(AppearanceSettings settings);
}

@page "/settings"
@using sv_b3b639e3aa074f7e82b5a699feff4e87.Services
@inject ISettingsService SettingsService
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-dashboard">
    <nav class="settings-sidebar">
        <ul>
            <li class="@(activeSection == "Profile" ? "active" : "")" @onclick='() => SetSection("Profile")'>
                <span class="nav-icon">👤</span> Profile
            </li>
            <li class="@(activeSection == "Notifications" ? "active" : "")" @onclick='() => SetSection("Notifications")'>
                <span class="nav-icon">🔔</span> Notifications
            </li>
            <li class="@(activeSection == "Security" ? "active" : "")" @onclick='() => SetSection("Security")'>
                <span class="nav-icon">🔒</span> Security
            </li>
            <li class="@(activeSection == "Appearance" ? "active" : "")" @onclick='() => SetSection("Appearance")'>
                <span class="nav-icon">🎨</span> Appearance
            </li>
        </ul>
    </nav>

    <main class="settings-content">
        @if (isLoading)
        {
            <div class="loading-spinner">Loading...</div>
        }
        else
        {
            @if (!string.IsNullOrEmpty(toastMessage))
            {
                <div class="toast @toastType">
                    @toastMessage
                    <button class="toast-close" @onclick="DismissToast">✕</button>
                </div>
            }

            @switch (activeSection)
            {
                case "Profile":
                    @RenderProfileSection()
                    break;
                case "Notifications":
                    @RenderNotificationsSection()
                    break;
                case "Security":
                    @RenderSecuritySection()
                    break;
                case "Appearance":
                    @RenderAppearanceSection()
                    break;
            }
        }
    </main>
</div>

@* Confirmation Dialog *@
@if (showConfirmDialog)
{
    <div class="dialog-overlay" @onclick="CancelConfirm">
        <div class="dialog" @onclick:stopPropagation="true">
            <h3>@confirmTitle</h3>
            <p>@confirmMessage</p>
            <div class="dialog-actions">
                <button class="btn btn-secondary" @onclick="CancelConfirm">Cancel</button>
                <button class="btn btn-danger" @onclick="ConfirmAction">Confirm</button>
            </div>
        </div>
    </div>
}

@code {
    private string activeSection = "Profile";
    private bool isLoading = true;
    private string? toastMessage;
    private string toastType = "success";

    // Profile state
    private string profileDisplayName = "";
    private string profileEmail = "";
    private string profileAvatarUrl = "";
    private string profileBio = "";
    private UserProfile? savedProfile;

    // Notifications state
    private bool emailNotifications;
    private bool pushNotifications;
    private bool weeklyDigest;
    private List<string> mutedChannels = new();
    private readonly List<string> availableChannels = new() { "general", "announcements", "updates", "marketing", "engineering" };

    // Security state
    private SecuritySettings? securitySettings;
    private bool changePasswordExpanded;
    private string currentPassword = "";
    private string newPassword = "";
    private string confirmPassword = "";
    private bool twoFactorEnabled;

    // Appearance state
    private string selectedTheme = "System";
    private string selectedFontSize = "Medium";
    private string selectedLanguage = "English";
    private bool compactMode;

    // Confirm dialog state
    private bool showConfirmDialog;
    private string confirmTitle = "";
    private string confirmMessage = "";
    private Func<Task>? confirmCallback;

    protected override async Task OnInitializedAsync()
    {
        await LoadSectionData();
    }

    private async Task SetSection(string section)
    {
        activeSection = section;
        isLoading = true;
        await LoadSectionData();
    }

    private async Task LoadSectionData()
    {
        try
        {
            switch (activeSection)
            {
                case "Profile":
                    var profile = await SettingsService.GetProfileAsync();
                    savedProfile = profile;
                    profileDisplayName = profile.DisplayName;
                    profileEmail = profile.Email;
                    profileAvatarUrl = profile.AvatarUrl;
                    profileBio = profile.Bio;
                    break;
                case "Notifications":
                    var prefs = await SettingsService.GetNotificationPrefsAsync();
                    emailNotifications = prefs.EmailNotifications;
                    pushNotifications = prefs.PushNotifications;
                    weeklyDigest = prefs.WeeklyDigest;
                    mutedChannels = new List<string>(prefs.MutedChannels);
                    break;
                case "Security":
                    securitySettings = await SettingsService.GetSecuritySettingsAsync();
                    twoFactorEnabled = securitySettings.TwoFactorEnabled;
                    changePasswordExpanded = false;
                    currentPassword = "";
                    newPassword = "";
                    confirmPassword = "";
                    break;
                case "Appearance":
                    var appearance = await SettingsService.GetAppearanceAsync();
                    selectedTheme = appearance.Theme;
                    selectedFontSize = appearance.FontSize;
                    selectedLanguage = appearance.Language;
                    compactMode = appearance.CompactMode;
                    break;
            }
        }
        catch (Exception ex)
        {
            ShowToast($"Error loading settings: {ex.Message}", "error");
        }
        finally
        {
            isLoading = false;
        }
    }

    private void ShowToast(string message, string type = "success")
    {
        toastMessage = message;
        toastType = type;
        _ = Task.Delay(3000).ContinueWith(_ => InvokeAsync(() =>
        {
            toastMessage = null;
            StateHasChanged();
        }));
    }

    private void DismissToast() => toastMessage = null;

    // --- Profile ---

    private async Task SaveProfile()
    {
        var profile = new UserProfile(profileDisplayName, profileEmail, profileAvatarUrl, profileBio);
        await SettingsService.SaveProfileAsync(profile);
        savedProfile = profile;
        ShowToast("Profile saved successfully!");
    }

    private void DiscardProfileChanges()
    {
        if (savedProfile is not null)
        {
            profileDisplayName = savedProfile.DisplayName;
            profileEmail = savedProfile.Email;
            profileAvatarUrl = savedProfile.AvatarUrl;
            profileBio = savedProfile.Bio;
        }
    }

    // --- Notifications ---

    private void ToggleMutedChannel(string channel)
    {
        if (mutedChannels.Contains(channel))
            mutedChannels.Remove(channel);
        else
            mutedChannels.Add(channel);
    }

    private async Task SaveNotifications()
    {
        var prefs = new NotificationPrefs(emailNotifications, pushNotifications, weeklyDigest, mutedChannels);
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        ShowToast("Notification preferences saved!");
    }

    // --- Security ---

    private async Task UpdatePassword()
    {
        if (newPassword != confirmPassword)
        {
            ShowToast("Passwords do not match.", "error");
            return;
        }
        if (string.IsNullOrWhiteSpace(currentPassword) || string.IsNullOrWhiteSpace(newPassword))
        {
            ShowToast("All password fields are required.", "error");
            return;
        }

        await SettingsService.ChangePasswordAsync(currentPassword, newPassword);
        currentPassword = "";
        newPassword = "";
        confirmPassword = "";
        changePasswordExpanded = false;
        ShowToast("Password updated successfully!");
    }

    private void RequestRevokeSession(string sessionId, string device)
    {
        confirmTitle = "Revoke Session";
        confirmMessage = $"Are you sure you want to revoke the session on \"{device}\"? This will sign out that device.";
        confirmCallback = async () => await RevokeSession(sessionId);
        showConfirmDialog = true;
    }

    private async Task RevokeSession(string sessionId)
    {
        await SettingsService.RevokeSessionAsync(sessionId);
        securitySettings = await SettingsService.GetSecuritySettingsAsync();
        ShowToast("Session revoked successfully.");
    }

    private async Task ConfirmAction()
    {
        showConfirmDialog = false;
        if (confirmCallback is not null)
            await confirmCallback();
    }

    private void CancelConfirm() => showConfirmDialog = false;

    // --- Appearance ---

    private async Task SaveAppearance()
    {
        var settings = new AppearanceSettings(selectedTheme, selectedFontSize, selectedLanguage, compactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        ShowToast("Appearance settings saved!");
    }

    // --- Render fragments ---

    private RenderFragment RenderProfileSection() => __builder =>
    {
        <h2>Profile Settings</h2>
        <div class="settings-section">
            <div class="avatar-preview">
                @if (!string.IsNullOrWhiteSpace(profileAvatarUrl))
                {
                    <img src="@profileAvatarUrl" alt="Avatar" class="avatar-img" />
                }
                else
                {
                    <div class="avatar-placeholder">No Avatar</div>
                }
                <p class="avatar-url-label">Avatar URL: @profileAvatarUrl</p>
            </div>

            <div class="form-group">
                <label for="displayName">Display Name</label>
                <input id="displayName" type="text" @bind="profileDisplayName" class="form-control" />
            </div>

            <div class="form-group">
                <label for="email">Email</label>
                <input id="email" type="email" @bind="profileEmail" class="form-control" />
            </div>

            <div class="form-group">
                <label for="bio">Bio</label>
                <textarea id="bio" @bind="profileBio" class="form-control" rows="4"></textarea>
            </div>

            <div class="form-actions">
                <button class="btn btn-primary" @onclick="SaveProfile">Save Changes</button>
                <button class="btn btn-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
            </div>
        </div>
    };

    private RenderFragment RenderNotificationsSection() => __builder =>
    {
        <h2>Notification Preferences</h2>
        <div class="settings-section">
            <div class="toggle-group">
                <label class="toggle-label">
                    <span>Email Notifications</span>
                    <label class="switch">
                        <input type="checkbox" @bind="emailNotifications" />
                        <span class="slider"></span>
                    </label>
                </label>

                <label class="toggle-label">
                    <span>Push Notifications</span>
                    <label class="switch">
                        <input type="checkbox" @bind="pushNotifications" />
                        <span class="slider"></span>
                    </label>
                </label>

                <label class="toggle-label">
                    <span>Weekly Digest</span>
                    <label class="switch">
                        <input type="checkbox" @bind="weeklyDigest" />
                        <span class="slider"></span>
                    </label>
                </label>
            </div>

            <h3>Muted Channels</h3>
            <div class="channel-list">
                @foreach (var channel in availableChannels)
                {
                    <label class="channel-item">
                        <input type="checkbox" checked="@mutedChannels.Contains(channel)"
                               @onchange="() => ToggleMutedChannel(channel)" />
                        <span>#@channel</span>
                    </label>
                }
            </div>

            <div class="form-actions">
                <button class="btn btn-primary" @onclick="SaveNotifications">Save Preferences</button>
            </div>
        </div>
    };

    private RenderFragment RenderSecuritySection() => __builder =>
    {
        <h2>Security Settings</h2>
        <div class="settings-section">
            <div class="expandable-panel">
                <button class="panel-header" @onclick="() => changePasswordExpanded = !changePasswordExpanded">
                    <span>Change Password</span>
                    <span class="expand-icon">@(changePasswordExpanded ? "▾" : "▸")</span>
                </button>
                @if (changePasswordExpanded)
                {
                    <div class="panel-body">
                        <div class="form-group">
                            <label for="currentPwd">Current Password</label>
                            <input id="currentPwd" type="password" @bind="currentPassword" class="form-control" />
                        </div>
                        <div class="form-group">
                            <label for="newPwd">New Password</label>
                            <input id="newPwd" type="password" @bind="newPassword" class="form-control" />
                        </div>
                        <div class="form-group">
                            <label for="confirmPwd">Confirm Password</label>
                            <input id="confirmPwd" type="password" @bind="confirmPassword" class="form-control" />
                        </div>
                        <button class="btn btn-primary" @onclick="UpdatePassword">Update Password</button>
                    </div>
                }
            </div>

            <div class="toggle-label" style="margin-top: 1.5rem;">
                <span>
                    Two-Factor Authentication
                    <span class="status-badge @(twoFactorEnabled ? "enabled" : "disabled")">
                        @(twoFactorEnabled ? "Enabled" : "Disabled")
                    </span>
                </span>
                <label class="switch">
